export const insertShapeToCanvas = (
  first: any,
  second: any,
  xOrOpts?: number | { x?: number; y?: number },
  yCoord?: number,
) => {
  const excalidrawAPI: ExcalidrawImperativeAPI | null =
    first && typeof first.getAppState === "function"
      ? first
      : second && typeof second.getAppState === "function"
      ? second
      : null;
  const shape: DrawioShapeDef = first && first.svg ? first : second;
  if (!excalidrawAPI || !shape) return;

  let x: number | undefined;
  let y: number | undefined;
  if (typeof xOrOpts === "object" && xOrOpts !== null) {
    x = xOrOpts.x;
    y = xOrOpts.y;
  } else {
    x = typeof xOrOpts === "number" ? xOrOpts : undefined;
    y = typeof yCoord === "number" ? yCoord : undefined;
  }

  const appState = excalidrawAPI.getAppState();
  const centerScene = viewportCoordsToSceneCoords(
    { clientX: window.innerWidth / 2, clientY: window.innerHeight / 2 },
    appState,
  );

  const shapeW = Math.round((shape.width || 52) * 1.25);
  const shapeH = Math.round((shape.height || 52) * 1.25);
  const targetX = x !== undefined ? Math.round(x) : Math.round(centerScene.x - shapeW / 2);
  const targetY = y !== undefined ? Math.round(y) : Math.round(centerScene.y - shapeH / 2);

  const currentElements = excalidrawAPI.getSceneElements();
  const groupId = randomId();

  // If native flowchart element with zero roughness (architectural precision)
  if (shape.isNative && shape.nativeType) {
    const mainElement = newElement({
      type: shape.nativeType,
      x: targetX,
      y: targetY,
      width: shapeW,
      height: shapeH,
      strokeColor: "#1e293b",
      backgroundColor: "#f8fafc",
      fillStyle: "solid",
      strokeWidth: 2,
      roughness: 0,
      roundness: shape.nativeType === "rectangle" ? { type: 3 } : null,
      groupIds: [groupId],
    });

    const textElement = newTextElement({
      text: shape.name,
      x: targetX + 8,
      y: targetY + shapeH / 2 - 8,
      fontSize: 14,
      fontFamily: 2,
      textAlign: "center",
      verticalAlign: "middle",
      strokeColor: "#0f172a",
      groupIds: [groupId],
    });

    excalidrawAPI.updateScene({
      elements: [...currentElements, mainElement, textElement],
      appState: {
        selectedElementIds: { [mainElement.id]: true, [textElement.id]: true },
      },
    });
    return;
  }

  // Create SVG image element + label with pure transparent background and architectural typography
  const fileId = randomId() as FileId;
  let svgMarkup = shape.svg;
  if (!svgMarkup.includes("width=")) {
    svgMarkup = svgMarkup.replace("<svg ", `<svg width="${shapeW}" height="${shapeH}" `);
  } else {
    svgMarkup = svgMarkup.replace(/\bwidth="[^"]*"/, `width="${shapeW}"`).replace(/\bheight="[^"]*"/, `height="${shapeH}"`);
  }
  const svgDataUrl = `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svgMarkup)))}` as DataURL;

  const fileData: BinaryFileData = {
    id: fileId,
    dataURL: svgDataUrl,
    mimeType: "image/svg+xml",
    created: Date.now(),
  };

  excalidrawAPI.addFiles([fileData]);

  const imageElement = newImageElement({
    type: "image",
    fileId,
    status: "saved",
    x: targetX,
    y: targetY,
    width: shapeW,
    height: shapeH,
    strokeColor: "transparent",
    groupIds: [groupId],
  });

  const labelElement = newTextElement({
    text: shape.name,
    x: targetX - 6,
    y: targetY + shapeH + 6,
    fontSize: 13,
    fontFamily: 2,
    textAlign: "center",
    verticalAlign: "middle",
    strokeColor: "#0f172a",
    groupIds: [groupId],
  });

  excalidrawAPI.updateScene({
    elements: [...currentElements, imageElement, labelElement],
    appState: {
      selectedElementIds: { [imageElement.id]: true, [labelElement.id]: true },
    },
  });
};
